def top3(mots):
    freq = {}
    for m in mots:
        if m in freq.keys():
            freq[m] = freq[m] + 1
        else:
            freq[m] = 1
    paires = sorted(freq.items(), key=lambda p: p[1])
    return paires[::-1][:3]
